-- JokeNet inside Shutap (Nov 16 2026). The Lab's in-house joke dataset moves
-- out of the founder's Excel (jokenet Master.xlsx) into this table, so it can
-- grow, be rated and tagged from /admin/jokenet, and feed the bit writer
-- live: the writer and the judge are shown the highest-rated lines whose
-- situations are closest in meaning to the story being written.
--
-- In-house only: written, selected and rated by Shutap. Users' stories and
-- bits never go in. Only the server (service role) reads or writes it; RLS
-- is on with no policies. Safe to run twice.
create extension if not exists vector;

create table if not exists public.jokenet (
  id bigint generated by default as identity primary key,
  situation text not null,
  joke text not null,
  -- 1 = dead · 3 = fine · 5 = would send unedited; null = not rated yet
  rating smallint check (rating between 1 and 5),
  slot text,
  archetype text,
  target text,
  tone text,
  heat smallint check (heat between 1 and 3),
  move text,
  mechanism text,
  voice text,
  -- me · shutap · contributor · dataset
  source text not null default 'me',
  -- own · CC-BY · CC0 · unclear (never publish unclear rows)
  license text not null default 'own',
  sent boolean not null default false,
  wins integer not null default 0,
  losses integer not null default 0,
  posted_on text,
  notes text,
  -- a line the founder wrote or edited herself: her own voice
  founder boolean not null default false,
  added_on date not null default ((now() at time zone 'America/Los_Angeles')::date),
  embedding vector(1536),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists jokenet_rating_idx on public.jokenet (rating desc) where archived_at is null;
create index if not exists jokenet_added_idx on public.jokenet (id desc);
create index if not exists jokenet_embedding_idx on public.jokenet using hnsw (embedding vector_cosine_ops);
alter table public.jokenet enable row level security;

create or replace function public.jokenet_touch() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;
drop trigger if exists jokenet_touch on public.jokenet;
create trigger jokenet_touch before update on public.jokenet for each row execute function public.jokenet_touch();

-- The lines the writer sees: rated at least min_rating, not archived, own
-- licence, nearest situations first.
create or replace function public.jokenet_match(
  q vector(1536),
  match_count int default 24,
  min_rating int default 4
)
returns table (id bigint, situation text, joke text, rating smallint, move text, mechanism text, founder boolean, source text, similarity float)
language sql stable security definer set search_path = public as $$
  select j.id, j.situation, j.joke, j.rating, j.move, j.mechanism, j.founder, j.source, 1 - (j.embedding <=> q) as similarity
  from public.jokenet j
  where j.archived_at is null
    and j.embedding is not null
    and j.rating >= min_rating
    and j.license in ('own', 'CC-BY', 'CC0')
  order by j.embedding <=> q
  limit match_count;
$$;
revoke all on function public.jokenet_match(vector, int, int) from public, anon, authenticated;

